import time
import numpy as np


def dot_flops_count(n: int) -> int:
    return int(2 * n)


def measure_dot_gflops(a_1d: np.ndarray, b_1d: np.ndarray, repeats: int = 7) -> dict:
    val = np.dot(a_1d, b_1d)
    timings = []
    for _ in range(max(1, repeats)):
        t0 = time.perf_counter()
        val = np.dot(a_1d, b_1d)
        t1 = time.perf_counter()
        timings.append(max(t1 - t0, 1e-9))
    median_sec = float(np.median(timings))
    flops = dot_flops_count(len(a_1d))
    gflops = float(flops / median_sec / 1e9)
    return {
        "dot_value": float(val),
        "elapsed_sec": median_sec,
        "gflops": gflops,
    }

