import torch


def fp16_underflow_grad(grad):
    return torch.tensor(grad, dtype=torch.float16).item()


def loss_scaled_step(weight, grad, lr, scale):
    scaled = torch.tensor(grad * scale, dtype=torch.float16)
    if not torch.isfinite(scaled):
        return weight
    return (torch.tensor(weight, dtype=torch.float32) - lr * (scaled.float() / scale)).item()


def dynamic_scaler_update(scale, found_inf):
    return max(1, scale / 2) if found_inf else min(65536, scale * 2)

import math
import torch


def online_softmax_update(m_prev, l_prev, block_scores):
    m = max(m_prev, block_scores.max().item())
    weights = torch.exp(block_scores - m)
    return m, l_prev * math.exp(m_prev - m) + weights.sum().item()


def online_attention_step(m_prev, l_prev, o_prev, block_scores, block_v):
    m, l = online_softmax_update(m_prev, l_prev, block_scores)
    o = o_prev * math.exp(m_prev - m) + torch.exp(block_scores - m) @ block_v
    return m, l, o


def tiled_attention(Q, K, V, block_size):
    rows = []
    for q in Q:
        m, l, o = -math.inf, 0.0, V.new_zeros(V.shape[1])
        for i in range(0, len(K), block_size):
            scores = K[i:i+block_size] @ q / math.sqrt(q.numel())
            m, l, o = online_attention_step(m, l, o, scores, V[i:i+block_size])
        rows.append(o / l)
    return torch.stack(rows)

