def bucket_timeline(ready_ms, sizes, cap, alpha_ms, bytes_per_ms):
    timeline = []
    used = 0
    for i, size in enumerate(sizes):
        used += size
        if i+1 == len(sizes) or used + sizes[i+1] > cap:
            start = max(ready_ms[i], timeline[-1][1] if timeline else 0)
            timeline.append([start, start + alpha_ms + used / bytes_per_ms, used])
            used = 0
    return timeline
